package science.transductive.nudge;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.Map;import science.transductive.nudge.core.MiniJson;
public final class WorkerClient {private final String base,bearer;public WorkerClient(String base,String bearer){String b=base.replaceAll("/+$","");if(!(b.startsWith("https://")||b.startsWith("http://127.0.0.1:")||b.startsWith("http://localhost:")))throw new IllegalArgumentException("remote controller must use HTTPS");this.base=b;this.bearer=bearer;}private HttpURLConnection open(String path,String method)throws IOException{URL u=URI.create(base+path).toURL();HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod(method);c.setConnectTimeout(8000);c.setReadTimeout(55000);c.setRequestProperty("Accept","application/json");if(bearer!=null&&!bearer.trim().isEmpty())c.setRequestProperty("Authorization","Bearer "+bearer);return c;}public String next(String device)throws IOException{return read(open("/v1/next?waitSeconds=45&device="+URLEncoder.encode(device,"UTF-8"),"GET"));}public String postEvent(String json,String eventId)throws IOException{HttpURLConnection c=open("/v1/events","POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Idempotency-Key",eventId);OutputStream o=c.getOutputStream();try{o.write(json.getBytes(StandardCharsets.UTF_8));}finally{o.close();}return read(c);}@SuppressWarnings("unchecked")public String uploadAudio(File f,String interactionId,String eventId)throws IOException{HttpURLConnection c=open("/v1/audio?interactionId="+URLEncoder.encode(interactionId,"UTF-8")+"&eventId="+URLEncoder.encode(eventId,"UTF-8"),"POST");c.setDoOutput(true);c.setFixedLengthStreamingMode(f.length());c.setRequestProperty("Content-Type","audio/mp4");c.setRequestProperty("Idempotency-Key",eventId);InputStream in=new FileInputStream(f);OutputStream out=c.getOutputStream();try{byte[]buf=new byte[16384];for(int n;(n=in.read(buf))!=-1;)out.write(buf,0,n);}finally{try{in.close();}finally{out.close();}}String body=read(c);Object o=MiniJson.parse(body);if(!(o instanceof Map))throw new IOException("audio response lacks audioRef");Object rv=((Map<?,?>)o).get("audioRef");if(!(rv instanceof String)||((String)rv).trim().isEmpty())throw new IOException("audio response lacks audioRef");return (String)rv;}private static byte[] all(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[]buf=new byte[8192];for(int n;(n=in.read(buf))!=-1;)b.write(buf,0,n);return b.toByteArray();}private static String read(HttpURLConnection c)throws IOException{int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();String body="";if(in!=null)try{body=new String(all(in),StandardCharsets.UTF_8);}finally{in.close();}if(code<200||code>=300)throw new IOException("HTTP "+code+" "+body);return body;}}
